        self.items = items

    def data(self, *keys: Tuple[int, str]) -> Dict[str, Any]:
        result = {}
        for key in keys:
            if isinstance(key, int):
                # Handle indexing
                if key < 0 or key >= len(self.items):
                    raise IndexError("Index out of bounds")
                result[key] = self.items[key]
            elif issubclass(key, AbstractElement):
                # Handle element indexing
                for child in key:
                    if child in self.items:
                        result[child] = self.items[child].data()
                    else:
                        if child.id is not None:
                            result[child.id] = None
                        else:
                            raise KeyError("Element not found in record")
            else:
                result[key] = self.items.get(key)
