from datetime import timedelta

def parse_frequency(frequency):
    if frequency is None or frequency == "always":
        return None

    number, unit = frequency.split()
    number = int(number)

    if unit.lower() == "seconds":
        return timedelta(seconds=number)
    elif unit.lower() == "minutes":
        return timedelta(minutes=number)
    elif unit.lower() == "hours":
        return timedelta(hours=number)
    elif unit.lower() == "days":
        return timedelta(days=number)
    elif unit.lower() == "weeks":
        return timedelta(weeks=number)
    elif unit.lower() == "months":
        return timedelta(days=number * 30)  # Using average month length for simplicity
    elif unit.lower() == "years":
        return timedelta(days=number * 365)  # Using average year length for simplicity
    else:
        raise ValueError("Unsupported time unit: " + unit)
