def parse(self, timestr, default=None,
              ignoretz=False, tzinfos=None, **kwargs):
    if default is None:
        default = datetime.datetime.utcnow().replace(microsecond=0, tzinfo=pytz.utc)
    if isinstance(timestr, datetime.datetime):
        if isinstance(default, datetime.datetime) and timestr == default:
            return default, ()
        if ignoretz is True:
            return timestr, ()
        raise ValueError("Cannot convert a datetime directly to a datetime with a timezone")

    try:
        tz = tzinfos.get(int(timestr[-6:]))
        if tz:
            timestr = timestr[:-6]
        return datetime.datetime.strptime(timestr, "%Y-%m-%d %H:%M:%S"), ()
    except ValueError:
        if ignoretz is True:
            return datetime.datetime.strptime(timestr, "%Y-%m-%d %H:%M:%S"), ()
        raise ValueError("Invalid date string format")

    # Handling fuzzy timestamps
    if 'fuzzy_with_tokens' in kwargs:
        fuzzy_format = kwargs['fuzzy_with_tokens']
        fuzzy_tokens = {}
        for t in fuzzy_format:
            fuzzy_tokens[t.replace("T", " ").replace("Z", "")] = t
        timestamp, tokens = self._parse(fuzzy_format, fuzzy_tokens=fuzzy_tokens)
        fuzzy_times = [parse(fuzzy_format, timestamp=formatted_timestr, fuzzy_with_tokens=fuzzy_format, **kwargs) for formatted_timestr in fuzzy_tokens.values()]
        if not fuzzy_times:
            raise ValueError("No valid fuzzy time found")
        return (min(fuzzy_times, key=lambda x: x[0])[0], tuple(t[1] for t in fuzzy_times))
